function readOccurrenceEditors(d,count){var profiles=C19OccurrenceModel.normalizeProfiles(d,count);app.querySelectorAll('[data-occurrence]').forEach(function(editor){var index=+editor.dataset.occurrence-1,p=profiles[index];if(!p)return;p.label=editor.querySelector('[data-occ-field="label"]').value.trim();p.duration=Math.min(999,Math.max(1,+editor.querySelector('[data-occ-field="duration"]').value||1));p.target=editor.querySelector('[data-occ-field="target"]').value;p.publics=Array.from(editor.querySelector('[data-occ-field="publics"]').selectedOptions).map(function(o){return o.value});p.location=editor.querySelector('[data-occ-field="location"]').value;p.entryService=editor.querySelector('[data-occ-field="entryService"]').value.trim();p.room=editor.querySelector('[data-occ-field="room"]').value});return profiles}
